function validate(input) {
  const [obj, spec] = input;
  if (obj === null || typeof obj !== 'object') return 'obj must be a JSON object or array.';
  if (JSON.stringify(obj).length > 100000) return 'Keep obj under 100,000 characters of JSON.';
  const stack = [[obj, 1]];
  while (stack.length) {
    const [item, depth] = stack.pop();
    if (item === null || typeof item !== 'object') continue;
    if (depth > 10) return 'Keep obj at most 10 levels deep.';
    if (!Array.isArray(item) && Object.hasOwn(item, '__proto__')) return 'Keys named "__proto__" are not allowed.';
    for (const key of Object.keys(item)) stack.push([item[key], depth + 1]);
  }
  const message = 'fn must be { "greaterThan": v }, { "lessThan": v }, { "typeIs": name }, { "equals": v }, "truthy" or "isArray".';
  if (spec === 'truthy' || spec === 'isArray') return null;
  if (spec === null || typeof spec !== 'object' || Array.isArray(spec) || Object.keys(spec).length !== 1) return message;
  const [name] = Object.keys(spec), value = spec[name];
  if (name === 'greaterThan' || name === 'lessThan') return Number.isFinite(value) ? null : `${name} needs a number.`;
  if (name === 'typeIs') return ['number', 'string', 'boolean', 'object'].includes(value) ? null : 'typeIs must be "number", "string", "boolean" or "object".';
  if (name === 'equals') return value === null || ['number', 'string', 'boolean'].includes(typeof value) ? null : 'equals needs a number, a string, a boolean or null.';
  return message;
}

