function adapt(input, solve, kit) {
  const [obj, spec] = input;
  const rule = spec === 'truthy' ? (x) => Boolean(x)
    : spec === 'isArray' ? (x) => Array.isArray(x)
    : 'greaterThan' in spec ? (x) => x > spec.greaterThan
    : 'lessThan' in spec ? (x) => x < spec.lessThan
    : 'typeIs' in spec ? (x) => typeof x === spec.typeIs
    : (x) => x === spec.equals;
  const fn = (x) => {
    const keep = rule(x);
    kit.trace(`fn(${JSON.stringify(x)}) returns ${keep}`);
    return keep;
  };
  const result = solve(JSON.parse(JSON.stringify(obj)), fn);
  if (result === undefined) {
    kit.trace('deepFilter returns undefined: nothing is left');
    return null;
  }
  if (result === null || typeof result !== 'object') throw new Error('deepFilter must return an object, an array or undefined.');
  // Serialize as LeetCode does, so an array element left as undefined shows up as null.
  const answer = JSON.parse(JSON.stringify(result));
  kit.trace(`deepFilter returns ${JSON.stringify(answer).slice(0, 80)}`);
  return answer;
}

