function deepFilter(obj, fn) {
  const isContainer = (value) => value !== null && typeof value === 'object';
  // A value is worth keeping when it is a passing leaf or holds one somewhere inside.
  const alive = (value) => (isContainer(value) ? Object.values(value).some(alive) : fn(value) === true);
  const copy = (value) => {
    if (!isContainer(value)) return value;
    if (Array.isArray(value)) return value.filter(alive).map(copy);
    return Object.fromEntries(Object.entries(value).filter(([, inner]) => alive(inner)).map(([key, inner]) => [key, copy(inner)]));
  };
  return alive(obj) ? copy(obj) : undefined;
}

