function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const int = (limit) => Math.floor(rand() * (2 * limit + 1)) - limit;
  const leaf = () => {
    const r = rand();
    if (r < 0.55) return int(small ? 6 : 1000);
    if (r < 0.75) return pick(['a', 'abc', '', '0', '2', '-3', '10', 'x y']);
    if (r < 0.9) return rand() < 0.5;
    return null;
  };
  const maxDepth = small ? 4 : 10;
  let left = small ? 1 + Math.floor(rand() * 12) : 2000;
  const container = (depth, length) => {
    const items = [];
    for (let i = 0; i < length && left > 0; i++) {
      left--;
      const nested = depth < maxDepth && rand() < (small ? 0.3 : 0.4);
      items.push(nested ? container(depth + 1, Math.floor(rand() * (small ? 4 : 6))) : leaf());
    }
    if (rand() < 0.5) return items;
    return Object.fromEntries(items.map((item, i) => [pick(['a', 'b', 'c', 'id', 'x', 'k']) + i, item]));
  };
  const obj = container(1, small ? Math.floor(rand() * 6) : 2000);
  const kind = pick(['greaterThan', 'greaterThan', 'lessThan', 'typeIs', 'typeIs', 'equals', 'truthy', 'isArray']);
  if (kind === 'truthy' || kind === 'isArray') return [obj, kind];
  if (kind === 'typeIs') return [obj, { typeIs: pick(['number', 'string', 'boolean', 'object']) }];
  if (kind === 'equals') return [obj, { equals: leaf() }];
  return [obj, { [kind]: int(small ? 6 : 1000) }];
}
